import * as THREE from 'three';
export function compareFernDepth(w){
 const r=w.renderer,q=w.groundDetails,near=q.meshes[0].mesh,depth=near.customDepthMaterial,previous=depth.userData.worldDepthCompatible,time=q.timeOverride;
 const size=r.getDrawingBufferSize(new THREE.Vector2()),target=new THREE.WebGLRenderTarget(size.x,size.y,{depthBuffer:false}),scene=new THREE.Scene(),camera=new THREE.Camera();
 const material=new THREE.ShaderMaterial({uniforms:{map:{value:w.destructionPass.smokeDepth.depthTexture}},vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:'#include <packing>\nvarying vec2 vUv;uniform sampler2D map;void main(){gl_FragColor=packDepthToRGBA(texture2D(map,vUv).r);}',depthTest:false,depthWrite:false,toneMapped:false});
 const geometry=new THREE.PlaneGeometry(2,2);scene.add(new THREE.Mesh(geometry,material));const originalTarget=r.getRenderTarget(),rows=[];
 function sample(enabled){depth.userData.worldDepthCompatible=enabled;w.destructionPass.captureDepth(w.camera,w.scene);const stats={...w.destructionPass.depthCaptureStats};r.setRenderTarget(target);r.render(scene,camera);const bytes=new Uint8Array(size.x*size.y*4);r.readRenderTargetPixels(target,0,0,size.x,size.y,bytes);r.setRenderTarget(originalTarget);return {bytes,stats};}
 try{for(const t of [0,2,5]){q.timeOverride=t;w.render(0);const a=sample(false),b=sample(true),c=sample(false);const visible=near.visible;let absent;try{near.visible=false;absent=sample(false);}finally{near.visible=visible;}let changed=0,repeat=0,max=0,control=0;for(let i=0;i<a.bytes.length;i+=4){let ab=false,ac=false,controlChanged=false;for(let k=0;k<4;k++){const delta=Math.abs(a.bytes[i+k]-b.bytes[i+k]);ab ||=delta!==0;ac ||=a.bytes[i+k]!==c.bytes[i+k];max=Math.max(max,delta);controlChanged ||=a.bytes[i+k]!==absent.bytes[i+k];}changed+=Number(ab);repeat+=Number(ac);control+=Number(controlChanged);}if(!control)throw Error("Depth control did not see near ferns");rows.push({removedFernPixels:control,time:t,changedPixels:changed,repeatPixels:repeat,maxByteDifference:max,base:a.stats,candidate:b.stats,near:q.near,far:q.far});}return rows;}
 finally{if(previous===undefined)delete depth.userData.worldDepthCompatible;else depth.userData.worldDepthCompatible=previous;q.timeOverride=time;r.setRenderTarget(originalTarget);geometry.dispose();material.dispose();target.dispose();}
}
